            Memo4.TabIndex = 5;
            Memo4.BackColor = System.Drawing.SystemColors.Control;
            Memo4.Multiline = true;
            Memo4.Text = "PETUNJUK :\n\r\n\r 1. Untuk membuat Aplikasi Pinjaman Baru, lakukan sbb :\n\r     - Pada tabel Daftar Kelompok, pilih kelompok yang dikehendaki\n\r     - Klik tombol Pilih Kelompok\n\r     - Apabila Kelompok terpilih masih memiliki Saldo Pinjaman yang belum lunas akan \n\r       muncul pesan peringatan.\n\r 2. Daftar pinjaman anggota kelompok dimasukkan setelah Aplikasi Pinjaman Baru \n\r     selesai diproses\n\r 3. Untuk memasukkan daftar pinjaman anggota , lakukan sbb :\n\r     - Klik tombol Edit Daftar Pinjaman Anggota Kelompok\n\r     - Pilih Kelompok pada daftar tabel kelompok\n\r     - Klik kolom No. P.K pada Daftar Tabel Pinjaman Kelompok\n\r     - Klik nama anggota pada tabel Daftar Anggota Kelompok\n\r     - Masukkan besaran pinjaman anggota pada isian Jumlah Pinjaman, \n\r       klik tombol Tambahkan Pinjaman Angota\n\r4. Untuk menghapus detil pinjaman anggota, lakukan sbb :\n\r     - Klik nama anggota pada tabel Daftar Pinjaman Anggota Kelompok\n\r     - Klik Tombol Hapus yang tersedia";
            Memo4.ReadOnly = true;
            Memo4.BorderStyle = System.Windows.Forms.BorderStyle.None;
